from hx import *
import math, itertools
def ol(steps): return '<ol>'+''.join(f'<li>{s}</li>' for s in steps)+'</ol>'
def cnt_div(a,b,ds): return sum(1 for x in range(a,b+1) if any(x%d==0 for d in ds))
def module():
    parts=[]
    # dữ liệu tính thật cho ví dụ
    A6915=cnt_div(1,5000,[6,9,15]); A69=cnt_div(1000,5000,[6,9])
    dvn=sum(math.comb(20,j)*math.comb(50,2*j) for j in range(0,21) if 6<=3*j<=12 and 2*j<=50)
    bs=(26**2+26**3)*(10**3+10**4)
    s=[]
    s.append(sl('<p>Bài toán <b>đếm</b> trả lời “có bao nhiêu cấu hình thỏa điều kiện?”. Chương 2 của giáo trình PTIT bắt đầu bằng ba công cụ nền: quy tắc cộng, quy tắc nhân và nguyên lý bù trừ. Nếu thiếu chúng thì mọi công thức tổ hợp phía sau chỉ là “học vẹt”.</p>'+ul(['Quy tắc cộng và quy tắc nhân','Quy tắc phần bù (đếm bằng cách trừ)','Nguyên lý bù trừ cho hai và ba tập, đếm số chia hết','Chia trường hợp và các bài đếm điển hình trong đề thi']),'MODULE 4 · Giáo trình 2016 §2.1–2.2 · Đề cương 2.2','Nguyên lý đếm cơ bản',
        explain='Đếm không có nghĩa là liệt kê từng cái. Đếm là tìm cách chia bài toán thành các bước hoặc trường hợp đủ đơn giản để nhân hoặc cộng lại.'))
    s.append(sl(formula('Quy tắc cộng','N(A ∪ B) = N(A) + N(B)   nếu A ∩ B = ∅',[('A, B','hai tập (hai cách làm) KHÔNG có phần tử chung'),('mở rộng','N(A₁ ∪ … ∪ A_m) = N(A₁) + … + N(A_m) nếu đôi một rời nhau')])+'<p>Dùng khi <b>chỉ chọn MỘT trong nhiều phương án loại trừ nhau</b>. Ví dụ: chọn 1 đề tài từ danh sách toán (23 đề), tin (15 đề) hoặc điện tử (19 đề): 23 + 15 + 19 = 57 cách.</p>','PHẦN 1 · Nền tảng','Quy tắc cộng'))
    s.append(sl(formula('Quy tắc nhân','N(A₁ × A₂ × … × A_m) = N(A₁)·N(A₂)·…·N(A_m)',[('bước i','có nᵢ cách chọn, KHÔNG phụ thuộc kết quả các bước trước (hoặc số cách vẫn là nᵢ)')])+'<p>Dùng khi <b>thực hiện liên tiếp nhiều bước</b>. Ví dụ biển số 2 chữ cái rồi 3 chữ số (được lặp): 26²·10³ = 676 000.</p>'+callout('info','Nhận diện','“VÀ / rồi / tiếp theo” → nhân; “HOẶC / một trong” → cộng.'),'PHẦN 1 · Nền tảng','Quy tắc nhân',
        explain='Nếu chọn áo (5 cách) rồi quần (4 cách) thì mỗi áo ghép với 4 quần: 5 hàng × 4 cột = 20 ô. Đó là nguồn gốc của phép nhân.'))
    s.append(sl(formula('Quy tắc phần bù','N(A) = N(X) − N(Aᶜ)',[('X','tập mọi cấu hình'),('Aᶜ','cấu hình KHÔNG thỏa tính chất')])+'<p>Cụm “ít nhất một” hầu như luôn nên đếm bằng phần bù. Ví dụ xâu nhị phân độ dài n có ít nhất một bit 0: 2ⁿ − 1.</p>','PHẦN 1 · Nền tảng','Quy tắc phần bù'))
    parts.append(dict(title='Nền tảng: cộng, nhân, phần bù',bullets=['Quy tắc cộng','Quy tắc nhân','Phần bù'],slides=s))
    s=[]
    s.append(sl(formula('Bù trừ hai tập','|A ∪ B| = |A| + |B| − |A ∩ B|')+formula('Bù trừ ba tập','|A∪B∪C| = Σ|Aᵢ| − Σ|Aᵢ∩Aⱼ| + |A∩B∩C|')+'<p>Tổng quát: cộng các giao lẻ tập, trừ các giao chẵn tập (dấu (−1)^(k+1) cho giao k tập).</p>','PHẦN 2 · Phương pháp','Nguyên lý bù trừ'))
    s.append(sl(formula('Đếm bội trong đoạn [a, b]','#{x ∈ [a,b] : d | x} = ⌊b/d⌋ − ⌊(a−1)/d⌋',[('d','số chia'),('⌊·⌋','phần nguyên (làm tròn xuống)')])+'<p>Chia hết cho <b>cả hai</b> số d₁, d₂ nghĩa là chia hết cho <b>BCNN</b>[d₁,d₂]. Dùng công thức trên với d = BCNN cho các giao.</p>'+sim('incl'),'PHẦN 2 · Phương pháp','Đếm số chia hết'))
    s.append(sl('<p>Nhiều bài thi yêu cầu <b>chia trường hợp</b> rồi cộng:</p>'+ul(['Biển số bắt đầu bằng 2 <i>hoặc</i> 3 chữ cái và kết thúc bằng 4 <i>hoặc</i> 5 chữ số: chia theo số chữ cái (2 hoặc 3) và số chữ số (4 hoặc 5), phần chữ cái và phần chữ số nhân nhau.','Đội văn nghệ có số nam bằng số nữ: chia theo số nữ j = 0,1,2,…, mỗi trường hợp C(nữ,j)·C(nam,j), lọc theo giới hạn số thành viên.'])+callout('good','Quy trình','1) chọn tiêu chí chia trường hợp sao cho các trường hợp LOẠI TRỪ nhau và ĐỦ; 2) đếm từng trường hợp bằng quy tắc nhân; 3) cộng lại.'),'PHẦN 2 · Phương pháp','Chia trường hợp'))
    parts.append(dict(title='Phương pháp: bù trừ và chia trường hợp',bullets=['Bù trừ 2 và 3 tập','Đếm số chia hết','Chia trường hợp'],slides=s))
    s=[]
    s.append(sl(callout('info','Ví dụ 1 (2.1.22b)','Biển số bắt đầu bằng 2 hoặc 3 chữ cái in hoa (26 chữ cái) và kết thúc bằng 4 hoặc 5 chữ số. Có bao nhiêu biển số?')+ol([f'Phần chữ cái: 26² + 26³ = {26**2+26**3}.',f'Phần chữ số: 10⁴ + 10⁵ = {10**4+10**5}.',f'Quy tắc nhân: {26**2+26**3}·{10**4+10**5} = <b>{bs:,}</b>'.replace(',','.')+'.']),'PHẦN 3 · Ví dụ','Ví dụ 1: biển số xe'))
    s.append(sl(callout('info','Ví dụ 2 (2.1.9b, đề 2023–2024)','Có bao nhiêu số nguyên trong đoạn từ 1 đến 5000 chia hết cho ít nhất một trong ba số 6, 9, 15?')+ol(['⌊5000/6⌋ = 833; ⌊5000/9⌋ = 555; ⌊5000/15⌋ = 333.','BCNN(6,9) = 18: 277; BCNN(6,15) = 30: 166; BCNN(9,15) = 45: 111.','BCNN(6,9,15) = 90: 55.',f'833 + 555 + 333 − 277 − 166 − 111 + 55 = <b>{A6915}</b>.']),'PHẦN 3 · Ví dụ','Ví dụ 2: bù trừ ba số'))
    s.append(sl(callout('info','Ví dụ 3 (2.1.5a, đề 2023–2024)','Lớp có 50 nam và 20 nữ. Có bao nhiêu cách chọn đội văn nghệ sao cho số nam đúng bằng 2 lần số nữ, đội có từ 6 đến 12 thành viên?')+ol(['Gọi số nữ là j thì số nam là 2j và tổng thành viên là 3j.','6 ≤ 3j ≤ 12 ⇒ j = 2, 3, 4.','Đáp án = C(20,2)·C(50,4) + C(20,3)·C(50,6) + C(20,4)·C(50,8) '+f'= <b>{dvn:,}</b>'.replace(',','.')+'.']),'PHẦN 3 · Ví dụ','Ví dụ 3: đội văn nghệ'))
    s.append(sl(callout('info','Ví dụ 4 (2.1.21b)','Từ mã máy tính là xâu độ dài 8 gồm 2 chữ cái (A–Z) và 6 chữ số (0–9), các ký tự ở vị trí bất kỳ. Có bao nhiêu từ mã?')+ol(['Chọn 2 vị trí cho chữ cái: C(8,2) = 28.','Xếp chữ cái: 26² = 676; xếp chữ số: 10⁶.',f'Tổng: 28·676·10⁶ = <b>{28*676*10**6:,}</b>'.replace(',','.')+'.']),'PHẦN 3 · Ví dụ','Ví dụ 4: từ mã'))
    parts.append(dict(title='Ví dụ có lời giải (câu hỏi thật của ngân hàng PTIT)',bullets=['Biển số','Bù trừ 3 số','Đội văn nghệ','Từ mã'],slides=s))
    s=[]
    s.append(sl(ul(['<b>Cộng ↔ nhân:</b> nhầm “HOẶC” với “VÀ”.','<b>Quên trừ phần giao</b> khi cộng các trường hợp có chồng lấn.','<b>BCNN, không phải tích:</b> số chia hết cho cả 6 và 9 là bội của 18, không phải của 54.','<b>Đầu mút đoạn:</b> dùng ⌊b/d⌋ − ⌊(a−1)/d⌋, không phải ⌊(b−a)/d⌋.','<b>Có thứ tự hay không:</b> “xếp hàng” dùng hoán vị; “chọn nhóm” dùng tổ hợp (Module 5).','<b>Chữ số đầu ≠ 0</b> khi đếm số có n chữ số.']),'PHẦN 4 · Bẫy và mở rộng','Sáu bẫy thường gặp'))
    s.append(sl('<p>Ba đề thi khác nhau cùng dùng một khung: đếm số nguyên KHÔNG chia hết cho a, b, c trong [1, N] = N − |A_a ∪ A_b ∪ A_c| = N − ⌊N/a⌋ − ⌊N/b⌋ − ⌊N/c⌋ + ⌊N/[a,b]⌋ + ⌊N/[a,c]⌋ + ⌊N/[b,c]⌋ − ⌊N/[a,b,c]⌋ (đề 2.1.8b, dạng tổng quát với ký hiệu N, a, b, c).</p>','PHẦN 4 · Bẫy và mở rộng','Mở rộng: đếm số KHÔNG chia hết'))
    parts.append(dict(title='Bẫy và mở rộng',bullets=['Sáu bẫy','Số không chia hết'],slides=s))
    s=[]
    s.append(sl('<p>Mật khẩu 8 ký tự từ 26 chữ cái thường và 10 chữ số, phải có ít nhất một chữ số. Số mật khẩu = 36⁸ − 26⁸ = 2 612 282 842 880 (phần bù: mật khẩu toàn chữ cái). Đây là lý do chính sách mật khẩu “bắt buộc có chữ số” chỉ giảm không gian tìm kiếm khoảng 7%.</p>','PHẦN 5 · Ứng dụng và ôn tập','Case study: không gian mật khẩu'))
    s.append(sl(ul(['Nhận diện cộng/nhân/phần bù.','Thuộc và dùng đúng công thức bù trừ 2, 3 tập.','Đếm bội trong đoạn bằng phần nguyên và BCNN.','Chia trường hợp có hệ thống (biển số, đội văn nghệ).'])+callout('good','Tiếp theo','Module 5: chỉnh hợp, tổ hợp, hoán vị lặp và đếm nghiệm nguyên có cận.'),'PHẦN 5 · Ứng dụng và ôn tập','Tổng kết'))
    parts.append(dict(title='Ứng dụng và tổng kết',bullets=['Mật khẩu','Checklist'],slides=s))
    notes='<h2>1. Nội dung chi tiết</h2><p>Hai quy tắc nền tảng được phát biểu qua tập hợp: nếu A, B rời nhau thì N(A ∪ B) = N(A) + N(B); tích Descartes có N(A × B) = N(A)·N(B). Nguyên lý bù trừ sửa lỗi “đếm hai lần” khi các tập giao nhau. Hầu hết bài đếm khó đều quy về việc chọn đúng tiêu chí chia trường hợp.</p><h2>2. Ví dụ chi tiết có lời giải</h2>'
    notes+=ex('1. Quy tắc cộng và nhân kết hợp','<p>Đi từ A đến C: qua B có 4 tuyến A→B và 3 tuyến B→C; hoặc đi thẳng theo 5 tuyến. Tổng: 4·3 + 5 = 17 cách (nhân trong từng phương án, cộng giữa các phương án).</p>')
    notes+=ex('2. Số điện thoại (2.1.3b)','<p>Mã quốc gia dài 1–3 chữ số, tiếp theo là 10 chữ số dạng NXX-NXX-XXXX với N ∈ {1..6}, X ∈ {0..9}.</p>'+ol(['Mã quốc gia: 10 + 10² + 10³ = 1110.','NXX: 6·10·10 = 600; NXX: 600; XXXX: 10⁴.','Tổng: 1110·600·600·10⁴ = 3 996 000 000 000 (khoảng 4·10¹²).'.replace('3 996 000 000 000','3.996.000.000.000')]))
    notes+=ex('3. Bù trừ hai số','<p>Từ 1000 đến 5000 có bao nhiêu số chia hết cho 6 hoặc 9? (2.1.2a)</p>'+ol(['Bội của 6: ⌊5000/6⌋ − ⌊999/6⌋ = 833 − 166 = 667.','Bội của 9: 555 − 111 = 444.','Bội của 18: 277 − 55 = 222.',f'667 + 444 − 222 = <b>{A69}</b>.']))
    notes+=ex('4. Sách xếp cạnh nhau (2.1.25a)','<p>15 cuốn: 5 Toán, 6 Vật lý, 4 Hóa (khác nhau); các cuốn cùng chủ đề nằm cạnh nhau. Xem mỗi chủ đề là một khối: 3! cách sắp khối, nhân 5!·6!·4! cách xếp trong khối: 6·120·720·24 = 12 441 600.</p>')
    notes+=ex('5. Xếp người cạnh nhau (2.1.25b)','<p>Xếp A,B,C,D,E,F thành hàng sao cho A cạnh B và C cạnh D: gộp thành hai khối (AB), (CD) cùng E, F: 4! = 24; mỗi khối 2 cách đổi chỗ: 24·2·2 = 96.</p>')
    notes+='<h2>3. Thực hành tương tác</h2><p>Nhập đoạn [a, b] và các số chia; công cụ liệt kê từng số hạng bù trừ và đối chiếu với đếm trực tiếp.</p>'+sim('incl')
    notes+='<h2>4. Bối cảnh lý thuyết và lịch sử</h2>'+callout('info','📜 Nguồn gốc','Nguyên lý bù trừ được hệ thống hóa trong thế kỷ 18–19 (liên quan đến Abraham de Moivre, Daniel da Silva và James Sylvester) và là công cụ đếm số hoán vị mất thứ tự. Các quy tắc cộng và nhân là cơ sở của đại số tổ hợp từ Pascal và Fermat (thế kỷ 17).')
    notes+='<h2>5. Case study</h2><p>Kích thước không gian tìm kiếm: mã PIN 4 chữ số có 10⁴ khả năng; ràng buộc “không có hai chữ số liền nhau giống nhau” còn 10·9³ = 7290. Mỗi ràng buộc là một lần dùng quy tắc nhân/phần bù để ước lượng độ khó bẻ khóa bằng vét cạn.</p><h2>6. Bẫy khi làm bài</h2>'+callout('warn','Chú ý','• Ghi rõ tiêu chí chia trường hợp và kiểm tra các trường hợp đủ và rời nhau.<br>• Với bài chia hết: liệt kê BCNN từng giao trước khi tính.<br>• Với biển số/mã: xác định chữ cái/chữ số có được lặp không.')
    return dict(id='m04',slug='04-nguyen-ly-dem',title='Nguyên lý đếm cơ bản',subtitle='Quy tắc cộng, nhân, phần bù, nguyên lý bù trừ',source='Giáo trình 2016 §2.1–2.2 · Đề cương INT1358 mục 2.2 · Rosen §6.1, §8.5',exam='Câu 2 (đếm) đề 2023–2024',time='≈ 2,5 giờ',
        objectives=['Chọn đúng quy tắc cộng hay nhân','Đếm bằng phần bù khi gặp “ít nhất”','Áp dụng bù trừ cho hai và ba tập, đếm số chia hết trong đoạn','Chia trường hợp đủ và rời nhau (biển số, đội văn nghệ, sách xếp)'],parts=parts,notes=notes,sims=['incl'])
